14	std::string read_text(const char *path) {
15	  std::ifstream input(path);
16	  if (!input) {
17	    throw std::runtime_error("input file could not be opened");
18	  }
19	  std::ostringstream buffer;
20	  buffer << input.rdbuf();
21	  return buffer.str();
22	}
