73	SubstructTerm::SubstructTerm(std::string aname, std::string asmarts, int ascore,
74	                             std::vector<int> reqElements,
75	                             std::string connSmarts)
76	    : name(std::move(aname)),
77	      smarts(std::move(asmarts)),
78	      score(ascore),
79	      requiredElements(std::move(reqElements)),
80	      connectivitySmarts(std::move(connSmarts)) {
81	  std::unique_ptr<ROMol> pattern(SmartsToMol(smarts));
82	  if (pattern) {
83	    matcher = std::move(*pattern);
84	  }
85	  // Initialize connectivity matcher if provided
86	  if (!connectivitySmarts.empty()) {
87	    std::unique_ptr<ROMol> connPattern(SmartsToMol(connectivitySmarts));
88	    if (connPattern) {
89	      connectivityMatcher = std::move(*connPattern);
90	    }
91	  }
92	}
