344	TautomerEnumerator::TautomerEnumerator(const CleanupParameters &params)
345	    : d_maxTautomers(params.maxTautomers),
346	      d_maxTransforms(params.maxTransforms),
347	      d_removeSp3Stereo(params.tautomerRemoveSp3Stereo),
348	      d_removeBondStereo(params.tautomerRemoveBondStereo),
349	      d_removeIsotopicHs(params.tautomerRemoveIsotopicHs),
350	      d_reassignStereo(params.tautomerReassignStereo) {
351	  std::unique_ptr<TautomerCatalogParams> tautParams;
352	  if (params.tautomerTransformData.empty()) {
353	    tautParams.reset(new TautomerCatalogParams(params.tautomerTransforms));
354	  } else {
355	    tautParams.reset(new TautomerCatalogParams(params.tautomerTransformData));
356	  }
357	  dp_catalog.reset(new TautomerCatalog(tautParams.get()));
358	}
