360	bool TautomerEnumerator::setTautomerStereoAndIsoHs(
361	    const ROMol &mol, ROMol &taut, const TautomerEnumeratorResult &res) const {
362	  bool modified = false;
363	  // Iterate only the atoms/bonds actually modified by transforms.
364	  for (auto atomIdx = res.d_modifiedAtoms.find_first();
365	       atomIdx != boost::dynamic_bitset<>::npos;
366	       atomIdx = res.d_modifiedAtoms.find_next(atomIdx)) {
367	    const auto atom = mol.getAtomWithIdx(static_cast<unsigned int>(atomIdx));
368	    auto tautAtom = taut.getAtomWithIdx(atomIdx);
369	    // clear chiral tag on sp2 atoms (also sp3 if d_removeSp3Stereo is true)
370	    if (tautAtom->getHybridization() == Atom::SP2 || d_removeSp3Stereo) {
371	      modified |= (tautAtom->getChiralTag() != Atom::CHI_UNSPECIFIED);
372	      tautAtom->setChiralTag(Atom::CHI_UNSPECIFIED);
373	      if (tautAtom->hasProp(common_properties::_CIPCode)) {
374	        tautAtom->clearProp(common_properties::_CIPCode);
375	      }
376	    } else {
377	      modified |= (tautAtom->getChiralTag() != atom->getChiralTag());
378	      tautAtom->setChiralTag(atom->getChiralTag());
379	      if (atom->hasProp(common_properties::_CIPCode)) {
380	        tautAtom->setProp(
381	            common_properties::_CIPCode,
382	            atom->getProp<std::string>(common_properties::_CIPCode));
383	      }
384	    }
385	    // remove isotopic Hs if present (and if d_removeIsotopicHs is true)
386	    if (tautAtom->hasProp(common_properties::_isotopicHs) &&
387	        (d_removeIsotopicHs || !tautAtom->getTotalNumHs())) {
388	      tautAtom->clearProp(common_properties::_isotopicHs);
389	    }
390	  }
391	  // Build bond lookup caches for the modified-bond sweep.
392	  // getBondWithIdx iterates through all bonds to find the one with the given
393	  // index, which is expensive when called multiple times in a loop.
394	  std::vector<const Bond *> molBonds;
395	  std::vector<Bond *> tautBonds;
396	  if (res.d_modifiedBonds.any()) {
397	    const auto numBonds = mol.getNumBonds();
398	    molBonds.resize(numBonds);
399	    tautBonds.resize(numBonds);
400	    for (auto bond : mol.bonds()) {
401	      molBonds[bond->getIdx()] = bond;
402	    }
403	    for (auto bond : taut.bonds()) {
404	      tautBonds[bond->getIdx()] = bond;
405	    }
406	  }
407	  for (auto bondIdx = res.d_modifiedBonds.find_first();
408	       bondIdx != boost::dynamic_bitset<>::npos;
409	       bondIdx = res.d_modifiedBonds.find_next(bondIdx)) {
410	    const auto bond = molBonds[bondIdx];
411	    std::vector<unsigned int> bondsToClearDirs;
412	    if (bond->getBondType() == Bond::DOUBLE &&
413	        bond->getStereo() > Bond::STEREOANY) {
414	      // look around the beginning and end atoms and check for bonds with
415	      // direction set
416	      for (auto atom : {bond->getBeginAtom(), bond->getEndAtom()}) {
417	        for (const auto &nbri :
418	             boost::make_iterator_range(mol.getAtomBonds(atom))) {
419	          const auto &obnd = mol[nbri];
420	          if (obnd->getBondDir() == Bond::ENDDOWNRIGHT ||
421	              obnd->getBondDir() == Bond::ENDUPRIGHT) {
422	            bondsToClearDirs.push_back(obnd->getIdx());
423	          }
424	        }
425	      }
426	    }
427	    auto tautBond = tautBonds[bondIdx];
428	    if (tautBond->getBondType() != Bond::DOUBLE || d_removeBondStereo) {
429	      // Apply the existing transformed-bond stereo cleanup policy.
430	      bool isRingBond = false;
431	      if (tautBond->getBondType() == Bond::DOUBLE) {
432	        auto ringInfo = taut.getRingInfo();
433	        if (!ringInfo || !ringInfo->isFindFastOrBetter()) {
434	          MolOps::fastFindRings(taut);
435	          ringInfo = taut.getRingInfo();
436	        }
437	        if (ringInfo) {
438	          const auto tbidx = tautBond->getIdx();
439	          const bool bondInRing = ringInfo->numBondRings(tbidx) != 0;
440	          const bool beginInRing =
441	              ringInfo->numAtomRings(tautBond->getBeginAtomIdx()) != 0;
442	          const bool endInRing =
443	              ringInfo->numAtomRings(tautBond->getEndAtomIdx()) != 0;
444	          isRingBond = bondInRing || (beginInRing && endInRing);
445	        }
446	      }
447	      const auto targetStereo = (tautBond->getBondType() == Bond::DOUBLE &&
448	                                 !isRingBond)
449	                                    ? Bond::STEREOANY
450	                                    : Bond::STEREONONE;
451	      modified |= (tautBond->getStereo() != targetStereo);
452	      tautBond->setStereo(targetStereo);
453	      tautBond->getStereoAtoms().clear();
454	      for (auto bi : bondsToClearDirs) {
455	        tautBonds[bi]->setBondDir(Bond::NONE);
456	      }
457	    } else {
458	      const INT_VECT &sa = bond->getStereoAtoms();
459	      modified |= (tautBond->getStereo() != bond->getStereo() ||
460	                   sa.size() != tautBond->getStereoAtoms().size());
461	      if (sa.size() == 2) {
462	        tautBond->setStereoAtoms(sa.front(), sa.back());
463	      }
464	      tautBond->setStereo(bond->getStereo());
465	      for (auto bi : bondsToClearDirs) {
466	        tautBonds[bi]->setBondDir(molBonds[bi]->getBondDir());
467	      }
468	    }
469	  }
470	  if (d_reassignStereo) {
471	    static const bool cleanIt = true;
472	    static const bool force = true;
473	    MolOps::assignStereochemistry(taut, cleanIt, force);
474	
475	    // Re-apply transformed-bond cleanup after stereo reassignment.
476	    if (d_removeBondStereo) {
477	      auto ringInfo = taut.getRingInfo();
478	      if (!ringInfo || !ringInfo->isFindFastOrBetter()) {
479	        MolOps::fastFindRings(taut);
480	        ringInfo = taut.getRingInfo();
481	      }
482	      for (auto bond : taut.bonds()) {
483	        const auto bondIdx = bond->getIdx();
484	        if (!res.d_modifiedBonds.test(bondIdx)) {
485	          continue;
486	        }
487	        if (bond->getBondType() != Bond::DOUBLE) {
488	          bond->setStereo(Bond::STEREONONE);
489	          bond->getStereoAtoms().clear();
490	          continue;
491	        }
492	
493	        const bool bondInRing = ringInfo && ringInfo->numBondRings(bondIdx);
494	        const bool beginInRing =
495	            ringInfo && ringInfo->numAtomRings(bond->getBeginAtomIdx());
496	        const bool endInRing =
497	            ringInfo && ringInfo->numAtomRings(bond->getEndAtomIdx());
498	        const bool isRingBond = bondInRing || (beginInRing && endInRing);
499	
