837	ROMol *TautomerEnumerator::pickCanonical(
838	    const TautomerEnumeratorResult &tautRes,
839	    boost::function<int(const ROMol &mol)> scoreFunc) const {
840	  ROMOL_SPTR bestMol;
841	  if (tautRes.d_tautomers.size() == 1) {
842	    bestMol = tautRes.d_tautomers.begin()->second.tautomer;
843	  } else {
844	    // Calculate score for each tautomer
845	    int bestScore = std::numeric_limits<int>::min();
846	    std::string bestSmiles = "";
847	    for (const auto &t : tautRes.d_tautomers) {
848	      auto score = scoreFunc(*t.second.tautomer);
849	#ifdef VERBOSE_ENUMERATION
850	      std::cerr << "  " << t.first << " " << score << std::endl;
851	#endif
852	      if (score > bestScore) {
853	        bestScore = score;
854	        bestSmiles = t.first;
855	        bestMol = t.second.tautomer;
856	      } else if (score == bestScore) {
857	        if (t.first < bestSmiles) {
858	          bestSmiles = t.first;
859	          bestMol = t.second.tautomer;
860	        }
861	      }
862	    }
863	  }
864	  ROMol *res = new ROMol(*bestMol);
865	  static const bool cleanIt = true;
866	  static const bool force = true;
867	  MolOps::assignStereochemistry(*res, cleanIt, force);
868	
869	  return res;
870	}
