37	    auto nbrBond = mol[nbri];
38	    if (nbrBond == &bond) {
39	      continue;
40	    }
41	    res.push_back(nbrBond);
42	  }
43	  for (auto nbri :
44	       boost::make_iterator_range(mol.getAtomBonds(bond.getEndAtom()))) {
45	    auto nbrBond = mol[nbri];
46	    if (nbrBond == &bond) {
47	      continue;
48	    }
49	    res.push_back(nbrBond);
50	  }
51	  return res;
52	}
