710	void canonicalizeDoubleBonds(ROMol &mol, const UINT_VECT &bondVisitOrders,
711	                             const UINT_VECT &atomVisitOrders,
712	                             std::vector<int8_t> &bondDirCounts,
713	                             std::vector<int8_t> &atomDirCounts,
714	                             const MolStack &molStack) {
715	  // start by removing the current directions on single bonds
716	  // around double bonds. At the same time, we build a prioritized
717	  // queue to decide the order in which we will canonicalize bonds.
718	
719	  // We want to start with bonds with the most neighboring stereo
720	  // bonds, and in case of ties, start with the bond that has
721	  // the lowest position in the molStack
722	
723	  auto getNeighboringStereoBond = [&mol](const Atom *dblBndAtom,
724	                                         const Bond *nbrBnd) -> Bond * {
725	    auto otherAtom = nbrBnd->getOtherAtom(dblBndAtom);
726	    for (const auto bond : mol.atomBonds(otherAtom)) {
727	      if (bond != nbrBnd && bond->getBondType() == Bond::DOUBLE &&
728	          bond->getStereo() > Bond::STEREOANY) {
729	        return bond;
730	      }
731	    }
732	    return nullptr;
733	  };
734	
735	  std::greater<const unsigned int &> molStackComparer;
736	  std::less<const unsigned int &> numStereoNbrsComparer;
737	
738	  std::unordered_map<const Bond *, std::vector<Bond *>> stereoBondNbrs;
739	  auto compareBondPriority = [&stereoBondNbrs, &bondVisitOrders,
740	                              &molStackComparer, &numStereoNbrsComparer](
741	                                 const Bond *aBnd, const Bond *bBnd) {
742	    const auto aNumStereoNbrs = stereoBondNbrs[aBnd].size();
743	    const auto bNumStereoNbrs = stereoBondNbrs[bBnd].size();
744	
745	    if (aNumStereoNbrs == bNumStereoNbrs) {
746	      return molStackComparer(bondVisitOrders[aBnd->getIdx()],
747	                              bondVisitOrders[bBnd->getIdx()]);
748	    }
749	    return numStereoNbrsComparer(aNumStereoNbrs, bNumStereoNbrs);
750	  };
751	
752	  std::priority_queue<Bond *, std::vector<Bond *>,
753	                      decltype(compareBondPriority)>
754	      q{compareBondPriority};
755	
756	  for (auto &msI : molStack) {
757	    if (msI.type != MOL_STACK_BOND) {
758	      // not a bond, skip it
759	      continue;
760	    }
761	
762	    auto bond = msI.obj.bond;
763	    Bond::BondDir dir = bond->getBondDir();
764	    if (dir == Bond::ENDDOWNRIGHT || dir == Bond::ENDUPRIGHT) {
765	      bond->setBondDir(Bond::NONE);
766	    }
767	
768	    if (bond->getBondType() != Bond::DOUBLE ||
769	        bond->getStereo() <= Bond::STEREOANY ||
770	        bond->getStereoAtoms().size() < 2) {
771	      // not a bond that can have stereo or that needs canonicalization
772	      bond->setStereo(Bond::STEREONONE);
773	      continue;
774	    }
775	
776	    auto &currentNbrs = stereoBondNbrs[bond];
777	    for (const auto *dblBondAtom : {bond->getBeginAtom(), bond->getEndAtom()}) {
778	      for (const auto *nbrBond : mol.atomBonds(dblBondAtom)) {
779	        if (!canHaveDirection(*nbrBond)) {
780	          continue;
781	        }
782	        auto nbrDblBnd = getNeighboringStereoBond(dblBondAtom, nbrBond);
783	        if (nbrDblBnd != nullptr) {
784	          currentNbrs.push_back(nbrDblBnd);
785	        }
786	      }
787	    }
788	    std::ranges::sort(currentNbrs, [&molStackComparer, &bondVisitOrders](
789	                                       const Bond *aBnd, const Bond *bBnd) {
790	      // Reversing the bonds is intentional: molStackComparer
791	      // is a std::greater comparer (priority queue returns
792	      // the highest element), but here we want to sort in
793	      // increasing order, so we want a std::less comparer,
794	      // which can be achieved by reversing the std::greater
795	      // because we can have no ties here
796	      return molStackComparer(bondVisitOrders[bBnd->getIdx()],
797	                              bondVisitOrders[aBnd->getIdx()]);
798	    });
799	
800	    q.emplace(bond);
801	  }
802	
803	  // Now that we have bonds in the order we want to handle them,
804	  // do the canonicalization
805	  std::vector<bool> seen_bonds(mol.getNumBonds());
806	  while (!q.empty()) {
807	    const auto bond = q.top();
808	    q.pop();
809	    if (seen_bonds[bond->getIdx()]) {
810	      continue;
811	    }
812	
813	    std::queue<Bond *> connectedBondsQ;
814	    connectedBondsQ.push(bond);
815	
816	    while (!connectedBondsQ.empty()) {
817	      const auto currentBond = connectedBondsQ.front();
818	      connectedBondsQ.pop();
819	      if (seen_bonds[currentBond->getIdx()]) {
820	        continue;
821	      }
822	
823	      Canon::canonicalizeDoubleBond(currentBond, bondVisitOrders,
824	                                    atomVisitOrders, bondDirCounts,
825	                                    atomDirCounts);
826	      seen_bonds[currentBond->getIdx()] = true;
827	      for (auto nbrStereoBnd : stereoBondNbrs[currentBond]) {
828	        if (!seen_bonds[nbrStereoBnd->getIdx()]) {
829	          connectedBondsQ.push(nbrStereoBnd);
830	        }
831	      }
832	    }
833	  }
834	
835	#if ENABLE_EXTRA_CHECKS
836	  checkDirCounts(mol, bondDirCounts, atomDirCounts);
837	#endif
838	}
