356	void canonicalizeDoubleBond(Bond *dblBond, const UINT_VECT &bondVisitOrders,
357	                            const UINT_VECT &atomVisitOrders,
358	                            std::vector<int8_t> &bondDirCounts,
359	                            std::vector<int8_t> &atomDirCounts) {
360	  PRECONDITION(dblBond, "bad bond");
361	  PRECONDITION(dblBond->getBondType() == Bond::DOUBLE, "bad bond order");
362	  PRECONDITION(dblBond->getStereo() > Bond::STEREOANY, "bad bond stereo");
363	  PRECONDITION(dblBond->getStereoAtoms().size() >= 2, "bad bond stereo atoms");
364	  PRECONDITION(atomVisitOrders[dblBond->getBeginAtomIdx()] > 0 ||
365	                   atomVisitOrders[dblBond->getEndAtomIdx()] > 0,
366	               "neither end atom traversed");
367	
368	  Atom *atom1 = dblBond->getBeginAtom();
369	  Atom *atom2 = dblBond->getEndAtom();
370	  // we only worry about double bonds that begin and end at atoms
371	  // of degree 2 or 3:
372	  if ((atom1->getDegree() != 2 && atom1->getDegree() != 3) ||
373	      (atom2->getDegree() != 2 && atom2->getDegree() != 3)) {
374	    return;
375	  }
376	  // ensure that atom1 is the lower numbered atom of the double bond (the one
377	  // traversed first)
378	  if (atomVisitOrders[dblBond->getBeginAtomIdx()] >=
379	      atomVisitOrders[dblBond->getEndAtomIdx()]) {
380	    std::swap(atom1, atom2);
381	  }
382	
383	  Bond *firstFromAtom1 = nullptr, *secondFromAtom1 = nullptr;
384	  Bond *firstFromAtom2 = nullptr, *secondFromAtom2 = nullptr;
385	
386	  ROMol &mol = dblBond->getOwningMol();
387	
388	  // -------------------------------------------------------
389	  // find the lowest visit order bonds from each end and determine
390	  // if anything is already constraining our choice of directions:
391	  bool dir1Set = false, dir2Set = false;
392	
393	  auto findNeighborBonds = [&mol, &dblBond, &bondDirCounts, &bondVisitOrders](
394	                               auto atom, auto &firstNeighborBond,
395	                               auto &secondNeighborBond, auto &dirSet) {
396	    auto firstVisitOrder = mol.getNumBonds() + 1;
397	    for (const auto bond : mol.atomBonds(atom)) {
398	      if (bond == dblBond || !canSetDoubleBondStereo(*bond)) {
399	        continue;
400	      }
401	
402	      auto bondIdx = bond->getIdx();
403	      if (bondDirCounts[bondIdx] > 0) {
404	        dirSet = true;
405	      }
406	      if (!firstNeighborBond || bondVisitOrders[bondIdx] < firstVisitOrder) {
407	        if (firstNeighborBond) {
408	          secondNeighborBond = firstNeighborBond;
409	        }
410	        firstNeighborBond = bond;
411	        firstVisitOrder = bondVisitOrders[bondIdx];
412	      } else {
413	        secondNeighborBond = bond;
414	      }
415	    }
416	  };
417	
418	  findNeighborBonds(atom1, firstFromAtom1, secondFromAtom1, dir1Set);
419	  findNeighborBonds(atom2, firstFromAtom2, secondFromAtom2, dir2Set);
420	
421	  // Make sure we found everything we need to find.
422	  //   This really shouldn't be a problem, but molecules can end up in odd
423	  //   states; for example, allenes can end up here. Instead of checking for
424	  //   them explicitly, exit early in any such possible state.
425	  if (!firstFromAtom1 || !firstFromAtom2) {
426	    return;
427	  }
428	
429	  // We interpret double bonds like this (this is a TRANS bond,
430	  // a CIS one would be similar, but both anchors would be either
431	  // above or below the double bond):
432	  //
433	  //   anchor1
434	  //          |
435	  //           atom1 === atom2
436	  //                          |
437	  //                           anchor2
438	  //
439	  // When parsing a SMILES, we expect anchor1 to come before atom1,
440	  // and atom2 before anchor2. But that is not always the case.
441	  // Inverting the order has effects on the bond directions, so
442	  // we define the variables below to help us find the right direction
443	  // for the bond directions. These are interpreted as follows:
444	  //
445	  // - firstFromAtom1 and secondFromAtom1 are considered "flipped" if
446	  // the anchor would come after the double bond start atom1, e.g.
447	  // in the SMILES C(\N)(/O)=C(/N)\O they are both flipped. Note
448	  // that, with this definition secondFromAtom1 is usually "flipped".
449	  //
450	  bool isFirstFromAtom1Flipped = [&]() {
451	    auto anchorIdx = firstFromAtom1->getOtherAtom(atom1)->getIdx();
452	    return (atomVisitOrders[atom1->getIdx()] < atomVisitOrders[anchorIdx]) !=
453	           firstFromAtom1->hasProp(
454	               common_properties::_TraversalRingClosureBond);
455	  }();
456	
457	  bool isSecondFromAtom1Flipped = [&]() {
458	    if (secondFromAtom1 == nullptr) {
459	      return false;
460	    }
461	    auto anchorIdx = secondFromAtom1->getOtherAtom(atom1)->getIdx();
462	    return (atomVisitOrders[atom1->getIdx()] < atomVisitOrders[anchorIdx]) !=
463	           secondFromAtom1->hasProp(
464	               common_properties::_TraversalRingClosureBond);
465	  }();
466	
467	  // - firstFromAtom2 and secondFromAtom2 are considered "flipped" if
468	  // the anchor atom comes before the double bond end atom2 (I think
469	  // this always requires rings to be involved). An example of firstFromAtom2
470	  //  being flipped would be the C atom in "C\N=2" in C=c1s/c2n(c1=O)CCCCC\N=2
471	
472	  bool isFirstFromAtom2Flipped = [&]() {
473	    auto anchorIdx = firstFromAtom2->getOtherAtom(atom2)->getIdx();
474	    return (atomVisitOrders[anchorIdx] < atomVisitOrders[atom2->getIdx()]) !=
475	           firstFromAtom2->hasProp(
476	               common_properties::_TraversalRingClosureBond);
477	  }();
478	
479	  bool isSecondFromAtom2Flipped = [&]() {
480	    if (secondFromAtom2 == nullptr) {
481	      return false;
482	    }
483	    auto anchorIdx = secondFromAtom2->getOtherAtom(atom2)->getIdx();
484	    return (atomVisitOrders[anchorIdx] < atomVisitOrders[atom2->getIdx()]) !=
485	           secondFromAtom2->hasProp(
486	               common_properties::_TraversalRingClosureBond);
487	  }();
488	
489	  // Both directions are already set. Update accounting
490	  // and check if both directions on each side are set.
491	  // We hit this in cases with cycles like CO/C1=C/C=C\C=C/C=N\1.
492	  if (dir1Set && dir2Set) {
493	    // Check that directions on atom1 side are present and consistent
494	    auto atom1DirsAreConsistent = true;
495	    if (secondFromAtom1) {
496	      if (!bondDirCounts[firstFromAtom1->getIdx()]) {
497	        setDirectionFromNeighboringBond(
498	            *secondFromAtom1, isSecondFromAtom1Flipped, *firstFromAtom1,
499	            isFirstFromAtom1Flipped);
500	      } else if (!bondDirCounts[secondFromAtom1->getIdx()]) {
501	        setDirectionFromNeighboringBond(
502	            *firstFromAtom1, isFirstFromAtom1Flipped, *secondFromAtom1,
503	            isSecondFromAtom1Flipped);
504	      } else {
505	        atom1DirsAreConsistent = sameSideDirsAreCompatible(
506	            *firstFromAtom1, *secondFromAtom1, isFirstFromAtom1Flipped,
507	            isSecondFromAtom1Flipped);
508	      }
509	
510	      bondDirCounts[secondFromAtom1->getIdx()] += 1;
511	      atomDirCounts[atom1->getIdx()] += 1;
512	    }
513	    bondDirCounts[firstFromAtom1->getIdx()] += 1;
514	    atomDirCounts[atom1->getIdx()] += 1;
515	
516	    // Check that directions on atom2 side are present and consistent
517	    auto atom2DirsAreConsistent = true;
518	    if (secondFromAtom2) {
519	      if (!bondDirCounts[firstFromAtom2->getIdx()]) {
520	        setDirectionFromNeighboringBond(
521	            *secondFromAtom2, isSecondFromAtom2Flipped, *firstFromAtom2,
522	            isFirstFromAtom2Flipped);
523	      } else if (!bondDirCounts[secondFromAtom2->getIdx()]) {
524	        setDirectionFromNeighboringBond(
525	            *firstFromAtom2, isFirstFromAtom2Flipped, *secondFromAtom2,
526	            isSecondFromAtom2Flipped);
527	      } else {
528	        atom2DirsAreConsistent = sameSideDirsAreCompatible(
529	            *firstFromAtom2, *secondFromAtom2, isFirstFromAtom2Flipped,
530	            isSecondFromAtom2Flipped);
531	      }
532	
533	      bondDirCounts[secondFromAtom2->getIdx()] += 1;
534	      atomDirCounts[atom2->getIdx()] += 1;
535	    }
536	    bondDirCounts[firstFromAtom2->getIdx()] += 1;
537	    atomDirCounts[atom2->getIdx()] += 1;
538	
539	    // Finally, check that directions across the double bond are consistent
540	    // with what we see on each end of the double bond
541	    if (!handleDirConflictsAcrossDoubleBond(
542	            *dblBond, *atom1, atom1DirsAreConsistent, *firstFromAtom1,
543	            isFirstFromAtom1Flipped, *secondFromAtom1, isSecondFromAtom1Flipped,
544	            *atom2, atom2DirsAreConsistent, *firstFromAtom2,
545	            isFirstFromAtom2Flipped, *secondFromAtom2, isSecondFromAtom2Flipped,
546	            bondDirCounts, atomDirCounts)) {
547	      logInconsistentBondDirsWarning(dblBond->getIdx());
548	    }
