559	    // directions to "arbitrary" values:
560	
561	    // the bond we came in on becomes ENDUPRIGHT:
562	    auto atom1Dir = Bond::ENDUPRIGHT;
563	    firstFromAtom1->setBondDir(atom1Dir);
