570	    if (bondDirCounts[firstFromAtom1->getIdx()] > 0) {
571	      // The first bond's direction has been set at some earlier point:
572	      bondDirCounts[firstFromAtom1->getIdx()] += 1;
573	      atomDirCounts[atom1->getIdx()] += 1;
574	
575	      if (secondFromAtom1 && bondDirCounts[secondFromAtom1->getIdx()]) {
576	        // both bonds have their directionalities set, check if
577	        // they are compatible.
