585	        }
586	
587	        bondDirCounts[secondFromAtom1->getIdx()] += 1;
588	        atomDirCounts[atom1->getIdx()] += 1;
589	      }
590	    } else {
591	      // the second bond must be present and setting the direction:
592	      CHECK_INVARIANT(secondFromAtom1, "inconsistent state");
593	      CHECK_INVARIANT(bondDirCounts[secondFromAtom1->getIdx()] > 0,
594	                      "inconsistent state");
595	
596	      setDirectionFromNeighboringBond(*secondFromAtom1,
597	                                      isSecondFromAtom1Flipped, *firstFromAtom1,
598	                                      isFirstFromAtom1Flipped);
599	
600	      // acknowledge that secondFromAtom1 is relevant for this bond,
601	      // and prevent removeRedundantBondDirSpecs from removing this
602	      // direction.
603	      bondDirCounts[secondFromAtom1->getIdx()] += 1;
604	
605	      bondDirCounts[firstFromAtom1->getIdx()] += 1;
606	      atomDirCounts[atom1->getIdx()] += 2;
607	      atom1ControllingBond = secondFromAtom1;
608	    }
609	  } else {
610	    // dir2 has been set, and dir1 hasn't: we're dealing with a stereochem
611	    // specification on a ring double bond:
612	    setFromBond1 = false;
613	    // at least one of the bonds on atom2 has its directionality set already:
614	    if (bondDirCounts[firstFromAtom2->getIdx()] > 0) {
615	      // The second bond's direction has been set at some earlier point:
616	      bondDirCounts[firstFromAtom2->getIdx()] += 1;
617	      atomDirCounts[atom2->getIdx()] += 1;
618	
619	      if (secondFromAtom2 && bondDirCounts[secondFromAtom2->getIdx()]) {
620	        // both bonds have their directionalities set, check if
