30	bool getAtropisomerAtomsAndBonds(const Bond *bond,
31	                                 AtropAtomAndBondVec atomsAndBondVects[2],
32	                                 const ROMol &mol) {
33	  PRECONDITION(bond, "no bond");
34	  atomsAndBondVects[0].first = bond->getBeginAtom();
35	  atomsAndBondVects[1].first = bond->getEndAtom();
36	
37	  // get the one or two bonds on each end
38	
39	  for (int bondAtomIndex = 0; bondAtomIndex < 2; ++bondAtomIndex) {
40	    for (const auto nbrBond :
41	         mol.atomBonds(atomsAndBondVects[bondAtomIndex].first)) {
42	      if (nbrBond == bond) {
43	        continue;  // a bond is NOT its own neighbor
44	      }
45	      atomsAndBondVects[bondAtomIndex].second.push_back(nbrBond);
46	    }
47	    if (atomsAndBondVects[bondAtomIndex].second.size() == 0) {
48	      return false;  // no neighbor bonds found
49	    }
50	
51	    // make sure the bond with this lowest atom is is first
52	
53	    if (atomsAndBondVects[bondAtomIndex].second.size() == 2 &&
54	        atomsAndBondVects[bondAtomIndex]
55	                .second[1]
56	                ->getOtherAtom(atomsAndBondVects[bondAtomIndex].first)
57	                ->getIdx() <
58	            atomsAndBondVects[bondAtomIndex]
59	                .second[0]
60	                ->getOtherAtom(atomsAndBondVects[bondAtomIndex].first)
61	                ->getIdx()) {
62	      std::swap(atomsAndBondVects[bondAtomIndex].second[0],
63	                atomsAndBondVects[bondAtomIndex].second[1]);
64	    }
65	  }
66	
67	  return true;
68	}
