70	bool getBondFrameOfReference(const Bond *bond, const Conformer *conf,
71	                             RDGeom::Point3D &xAxis, RDGeom::Point3D &yAxis,
72	                             RDGeom::Point3D &zAxis) {
73	  // create a frame of reference that has its X-axis along the atrop bond
74	  // for 2D confs, the yAxis is in the 2D plane and the zAxis is perpendicular
75	  // to that plane) for 3D confs  the yAxis and the zAxis are arbitrary.
76	
77	  PRECONDITION(bond, "bad bond");
78	
79	  xAxis = conf->getAtomPos(bond->getEndAtom()->getIdx()) -
80	          conf->getAtomPos(bond->getBeginAtom()->getIdx());
81	  if (xAxis.length() < REALLY_SMALL_BOND_LEN) {
82	    return false;  // bond len is xero
83	  }
84	  xAxis.normalize();
85	  if (!conf->is3D()) {
86	    yAxis = RDGeom::Point3D(-xAxis.y, xAxis.x, 0);
87	    yAxis.normalize();
88	    zAxis = RDGeom::Point3D(0.0, 0.0, 1.0);
89	    return true;
90	  }
91	
92	  // here for 3D conf
93	
94	  if (fabs(xAxis.x) > REALLY_SMALL_BOND_LEN ||
95	      fabs(xAxis.y) > REALLY_SMALL_BOND_LEN) {
96	    zAxis = RDGeom::Point3D(
97	        0, 0, 1);  // since X or Y value of the new x xaxis is NOT 0, this
98	                   // new temp z axis cannnot be colinear with it
99	  } else {
100	    zAxis = RDGeom::Point3D(1, 0, 0);  // since the new x axis is exactly along
101	                                       // the (old) z axis, this new temp z axis
102	                                       // is NOT colinear with it
103	  }
104	
105	  yAxis = zAxis.crossProduct(xAxis);
106	  zAxis = xAxis.crossProduct(yAxis);
107	  yAxis.normalize();
108	  zAxis.normalize();
109	
110	  return true;
111	}
