153	Bond::BondDir getBondDirForAtropisomer2d(RDGeom::Point3D bondVecs[2],
154	                                         Bond::BondStereo bondStereo,
155	                                         unsigned int whichEnd,
156	                                         unsigned int whichBond) {
157	  PRECONDITION(whichEnd <= 1, "whichEnd must be 0 or 1");
158	  PRECONDITION(whichBond <= 1, "whichBond must be 0 or 1");
159	  PRECONDITION(bondStereo == Bond::BondStereo::STEREOATROPCW ||
160	                   bondStereo == Bond::BondStereo::STEREOATROPCCW,
161	               "bondStereo must be BondAtropisomerCW or BondAtropisomerCCW");
162	
163	  int flips = 0;
164	  if (bondStereo == Bond::BondStereo::STEREOATROPCCW) {
165	    ++flips;
166	  }
167	  if (whichBond == 1) {
168	    ++flips;
169	  }
170	  if (whichEnd == 1) {
171	    ++flips;
172	  }
173	  if (bondVecs[1 - whichEnd].y < 0) {
174	    ++flips;  // if the OTHER end is negative for the low index bond vec, it
175	              // is a flip
176	  }
177	
178	  return flips % 2 ? Bond::BEGINWEDGE : Bond::BEGINDASH;
179	}
