181	Bond::BondDir getBondDirForAtropisomer3d(Bond *whichBond,
182	                                         const Conformer *conf) {
183	  // for 3D we mark it as wedge or hash depending on the z-value of the bond
184	  // vector
185	  //  IT really doesn't matter since we ignore these except as MARKERS for
186	  //  which bonds are atropisomer bonds
187	  if ((conf->getAtomPos(whichBond->getEndAtom()->getIdx()).z -
188	       conf->getAtomPos(whichBond->getBeginAtom()->getIdx()).z) >
189	      REALLY_SMALL_BOND_LEN) {
190	    return Bond::BondDir::BEGINWEDGE;
191	  } else {
192	    return Bond::BondDir::BEGINDASH;
