196	bool getAtropIsomerEndVect(const AtropAtomAndBondVec &atomAndBondVec,
197	                           const RDGeom::Point3D &yAxis,
198	                           const RDGeom::Point3D &zAxis, const Conformer *conf,
199	                           RDGeom::Point3D &bondVec) {
200	  PRECONDITION(
201	      atomAndBondVec.second.size() > 0 && atomAndBondVec.second.size() < 3,
202	      "bad bond size");
203	  PRECONDITION(atomAndBondVec.second[0], "bad first bond");
204	  PRECONDITION(atomAndBondVec.second.size() == 1 || atomAndBondVec.second[1],
205	               "bad second bond");
206	
207	  bondVec = conf->getAtomPos(atomAndBondVec.second[0]
208	                                 ->getOtherAtom(atomAndBondVec.first)
209	                                 ->getIdx()) -
210	            conf->getAtomPos(
211	                atomAndBondVec.first->getIdx());  // in old frame of reference
212	
213	  bondVec = RDGeom::Point3D(0.0, bondVec.dotProduct(yAxis),
214	                            bondVec.dotProduct(zAxis));  // in new frame
215	
216	  // make sure the other atom is on the other side
217	
218	  if (atomAndBondVec.second.size() == 2) {
219	    RDGeom::Point3D otherVec =
220	        conf->getAtomPos(atomAndBondVec.second[1]
221	                             ->getOtherAtom(atomAndBondVec.first)
222	                             ->getIdx()) -
223	        conf->getAtomPos(
224	            atomAndBondVec.first->getIdx());  // in old frame of reference
225	    otherVec = RDGeom::Point3D(0.0, otherVec.dotProduct(yAxis),
226	                               otherVec.dotProduct(zAxis));  // in new frame
227	
228	    if (bondVec.length() < REALLY_SMALL_BOND_LEN) {
229	      bondVec = -otherVec;  // put it on the other side of otherVec
230	    } else if (bondVec.dotProduct(otherVec) > REALLY_SMALL_BOND_LEN) {
231	      // the product of dotproducts (y-values) should be
232	      // negative (or at least zero)
233	      BOOST_LOG(rdWarningLog)
234	          << "Both bonds on one end of an atropisomer are on the same side - atoms is : "
235	          << atomAndBondVec.first->getIdx() << std::endl;
236	      return false;
237	    }
238	  }
239	  if (bondVec.length() < REALLY_SMALL_BOND_LEN) {
240	    BOOST_LOG(rdWarningLog)
241	        << "Could not find a bond on one end of an atropisomer that is not co-linear - atoms are : "
242	        << atomAndBondVec.first->getIdx() << std::endl;
243	    return false;
244	  }
245	
246	  bondVec.normalize();
247	  return true;
248	}
