250	std::pair<bool, Bond::BondDir> getBondDir(
251	    const Bond *bond, const AtropAtomAndBondVec &atomAndBondVec) {
252	  // get the wedge dir for this end of the bond
253	  // if the first bond 1 has a bondDir, use it
254	  // if the second bond has a bond dir use the opposite of if
255	  // if both bonds have a dir, make sure they are different
256	
257	  auto bond1Dir = atomAndBondVec.second[0]->getBondDir();
258	  if (bond1Dir != Bond::BEGINWEDGE && bond1Dir != Bond::BEGINDASH) {
259	    bond1Dir = Bond::NONE;  //  we dont care if it any thing else
260	  }
261	  auto bond2Dir = atomAndBondVec.second.size() == 2
262	                      ? atomAndBondVec.second[1]->getBondDir()
263	                      : Bond::NONE;
264	  if (bond2Dir != Bond::BEGINWEDGE && bond2Dir != Bond::BEGINDASH) {
265	    bond2Dir = Bond::NONE;
266	  }
267	
268	  // if both are set to a direction, they must NOT be the same - one
269	  // must be a dash and the other a hash
270	
271	  if (bond1Dir != Bond::NONE && bond2Dir != Bond::NONE &&
272	      bond1Dir == bond2Dir) {
273	    BOOST_LOG(rdWarningLog)
274	        << "The bonds on one end of an atropisomer are both UP or both DOWN - atoms are: "
275	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
276	    return {false, Bond::BondDir::NONE};
277	  }
278	
279	  if (bond1Dir == Bond::BEGINWEDGE || bond2Dir == Bond::BEGINDASH) {
280	    return {true, Bond::BondDir::BEGINWEDGE};
281	  }
282	  if (bond1Dir == Bond::BEGINDASH || bond2Dir == Bond::BEGINWEDGE) {
283	    return {true, Bond::BondDir::BEGINDASH};
284	  }
285	  return {true, Bond::BondDir::NONE};
286	}
