289	                                       const Conformer *conf) {
290	  // the approach is this:
291	  // we will view the system along the line from the potential atropisomer
292	  // bond, from atom1 to atom 2 and we do a coordinate transformation to
293	  // the plane of reference where that vector, from a1 to a2, is the x-AXIS.
294	  // For 2D, the y axis is in the 2D plane, and the zaxis is perpendicaul to
295	  // the 2D plane For 3D, the Y and Z axes are taken arbitrarily to form
296	  // a right-handed system with the X-axis.
297	  //  atoms 1 and 2 each have one or two bonds out from the main potential
298	  //  atrop bond. for each end of the main bond, we find a vector to reprent
299	  //  the neighbor atom with the smallest index as its projection onto the
300	  //  x=0 plane.
301	  // (In 2d, this projection is on the y-AXIS for the end that does NOT have
302	  // a wedge/hash bond, and  on the z axis - out of the plane - for the end
303	  // that does have a wedge/hash). The chirality is recorded as the
304	  // direction we rotate from, atom 1's projection to atom2's proejection -
305	  // either clockwise or counter clockwise
306	
307	  PRECONDITION(bond, "bad bond");
308	
309	  // one vector for each end - each one - should end up with 1 or 2 entries
310	  AtropAtomAndBondVec atomAndBondVecs[2];
311	  if (!getAtropisomerAtomsAndBonds(bond, atomAndBondVecs, mol)) {
312	    return;  // not an atropisomer
313	  }
314	
315	  // make sure we do not have wiggle bonds
316	
317	  for (auto atomAndBondVec : atomAndBondVecs) {
318	    for (auto endBond : atomAndBondVec.second) {
319	      if (endBond->getBondDir() == Bond::UNKNOWN) {
320	        return;  // not an atropisomer
321	      }
322	    }
323	  }
324	
325	  // the convention is that in the absence of coords, the coordiates are choosen
326	  // with the lowest numbered atom of the atrop bond down, and the other atom
327	  // straight up.
328	  // On each end, the lowest numbered connecting atom is on the left
329	  //
330	  //              a      b
331	  //               \   /
332	  //                 c
333	  //                 |
334	  //                 d
335	  //               /   \     aaa
336	  //              e      f
337	  //
338	  // where  c > d
339	  //        a < b
340	  //        e < f
