342	  if (conf == nullptr) {
343	    std::pair<bool, Bond::BondDir> bond1DirResult;
344	    bond1DirResult = getBondDir(bond, atomAndBondVecs[0]);
345	    if (!bond1DirResult.first) {
346	      return;
347	    }
348	    std::pair<bool, Bond::BondDir> bond2DirResult;
349	    bond2DirResult = getBondDir(bond, atomAndBondVecs[1]);
350	    if (!bond2DirResult.first) {
351	      return;
352	    }
353	    if (bond1DirResult.second == bond2DirResult.second) {
354	      BOOST_LOG(rdWarningLog)
355	          << "inconsistent bond wedging for an atropisomer.  Atoms are: "
356	          << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
357	          << std::endl;
358	      return;
359	    }
