401	      }
402	
403	      if (!getAtropIsomerEndVect(atomAndBondVecs[bondAtomIndex], yAxis, zAxis,
404	                                 conf, bondVecs[bondAtomIndex])) {
405	        return;
406	      }
407	
408	      if (bondDirResult.second == Bond::BEGINWEDGE) {
409	        bondVecs[bondAtomIndex].y *= 0.707;
410	        bondVecs[bondAtomIndex].z = fabs(bondVecs[bondAtomIndex].y);
411	      } else if (bondDirResult.second == Bond::BEGINDASH) {
412	        bondVecs[bondAtomIndex].y *= 0.707;
413	        bondVecs[bondAtomIndex].z = -fabs(bondVecs[bondAtomIndex].y);
414	      }
415	    } else {  // the conf is 3D
416	      // to be considered, one or more neighbor bonds must have a wedge or
417	      // hash
418	
419	      // find the projection of the bond(s) on this end in the frame of
420	      // reference's  x=0  plane
421	      RDGeom::Point3D tempBondVec =
422	          conf->getAtomPos(
423	              atomAndBondVecs[bondAtomIndex]
424	                  .second[0]
425	                  ->getOtherAtom(atomAndBondVecs[bondAtomIndex].first)
426	                  ->getIdx()) -
427	          conf->getAtomPos(atomAndBondVecs[bondAtomIndex].first->getIdx());
428	      bondVecs[bondAtomIndex] = RDGeom::Point3D(
429	          0.0, tempBondVec.dotProduct(yAxis), tempBondVec.dotProduct(zAxis));
430	
431	      if (atomAndBondVecs[bondAtomIndex].second.size() == 2) {
432	        tempBondVec =
433	            conf->getAtomPos(
434	                atomAndBondVecs[bondAtomIndex]
435	                    .second[1]
436	                    ->getOtherAtom(atomAndBondVecs[bondAtomIndex].first)
437	                    ->getIdx()) -
438	            conf->getAtomPos(atomAndBondVecs[bondAtomIndex].first->getIdx());
439	
440	        // get the projection of the 2nd bond on the x=0 plane
441	
442	        RDGeom::Point3D otherBondVec = RDGeom::Point3D(
443	            0.0, tempBondVec.dotProduct(yAxis), tempBondVec.dotProduct(zAxis));
444	
445	        // if the first atom is co-linear with the main atrop bond, use
446	        // the opposite of the 2nd atom
447	
448	        if (bondVecs[bondAtomIndex].length() < REALLY_SMALL_BOND_LEN) {
449	          bondVecs[bondAtomIndex] =
450	              -otherBondVec;  // note - it might still be co-linear-
451	                              // this is checked below
452	        } else if (bondVecs[bondAtomIndex].dotProduct(otherBondVec) >
453	                   REALLY_SMALL_BOND_LEN) {
454	          BOOST_LOG(rdWarningLog)
455	              << "Both bonds on one end of an atropisomer are on the same side - atoms are: "
456	              << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
457	              << std::endl;
458	          return;
459	        }
460	      }
461	
462	      if (bondVecs[bondAtomIndex].length() < REALLY_SMALL_BOND_LEN) {
463	        BOOST_LOG(rdWarningLog)
464	            << "Failed to find a bond on one end of an atropisomer that is NOT co-linear - atoms are: "
465	            << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
466	            << std::endl;
467	        return;
468	      }
469	    }
470	  }
471	
472	  auto crossProduct = bondVecs[1].crossProduct(bondVecs[0]);
473	
474	  if (crossProduct.x > REALLY_SMALL_BOND_LEN) {
475	    bond->setStereo(Bond::BondStereo::STEREOATROPCCW);
476	  } else if (crossProduct.x < -REALLY_SMALL_BOND_LEN) {
477	    bond->setStereo(Bond::BondStereo::STEREOATROPCW);
478	  } else {
479	    BOOST_LOG(rdWarningLog)
480	        << "The 2 defining bonds for an atropisomer are co-planar - atoms are: "
481	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
482	    return;
483	  }
484	}
