486	void cleanupAtropisomerStereoGroups(ROMol &mol) {
487	  std::vector<StereoGroup> newsgs;
488	  for (auto sg : mol.getStereoGroups()) {
489	    std::vector<Atom *> okatoms;
490	    std::vector<Bond *> okbonds;
491	
492	    for (auto atom : sg.getAtoms()) {
493	      bool foundAtrop = false;
494	      for (auto bndI : boost::make_iterator_range(mol.getAtomBonds(atom))) {
495	        auto bond = (mol)[bndI];
496	        if (bond->getStereo() == Bond::BondStereo::STEREOATROPCCW ||
497	            bond->getStereo() == Bond::BondStereo::STEREOATROPCW) {
498	          foundAtrop = true;
499	          if (std::find(okbonds.begin(), okbonds.end(), bond) ==
500	              okbonds.end()) {
501	            okbonds.push_back(bond);
502	          }
503	        }
504	      }
505	
506	      if (!foundAtrop) {
507	        okatoms.push_back(atom);
508	      }
509	    }
510	
511	    if (okbonds.empty()) {
512	      newsgs.push_back(sg);
513	    } else {
514	      newsgs.emplace_back(sg.getGroupType(), std::move(okatoms),
515	                          std::move(okbonds));
516	    }
517	  }
518	  mol.setStereoGroups(std::move(newsgs));
519	}
