800	bool WedgeBondFromAtropisomerOneBond2d(
801	    Bond *bond, const ROMol &mol, const Conformer *conf,
802	    std::map<int, std::unique_ptr<RDKit::Chirality::WedgeInfoBase>>
803	        &wedgeBonds) {
804	  PRECONDITION(bond, "no bond");
805	
806	  AtropAtomAndBondVec atomAndBondVecs[2];
807	  if (!getAtropisomerAtomsAndBonds(bond, atomAndBondVecs, mol)) {
808	    return false;  // not an atropisomer
809	  }
810	
811	  //  make sure we do not have wiggle bonds
812	
813	  for (auto atomAndBondVec : atomAndBondVecs) {
814	    for (auto endBond : atomAndBondVec.second) {
815	      if (endBond->getBondDir() == Bond::UNKNOWN) {
816	        return false;  // not an atropisomer)
817	      }
818	    }
819	  }
820	
821	  // create a frame of reference that has its X-axis along the atrop bond
822	
823	  RDGeom::Point3D xAxis, yAxis, zAxis;
824	
825	  if (!getBondFrameOfReference(bond, conf, xAxis, yAxis, zAxis)) {
826	    // connot percieve atroisomer bond
827	
828	    BOOST_LOG(rdWarningLog)
829	        << "Cound not get a frame of reference for an atropisomer bond - atoms are: "
830	        << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx() << std::endl;
831	    return false;
832	  }
833	
834	  RDGeom::Point3D bondVecs[2];  // one bond vector from each end of the
835	                                // potential atropisome bond
836	
837	  for (int bondAtomIndex = 0; bondAtomIndex < 2; ++bondAtomIndex) {
838	    // find a vector to represent the lowest numbered atom on each end
839	    // this vector is NOT the bond vector, but is y-value in the bond
840	    // frame or reference
841	
842	    if (!getAtropIsomerEndVect(atomAndBondVecs[bondAtomIndex], yAxis, zAxis,
843	                               conf, bondVecs[bondAtomIndex])) {
844	      return false;
845	    }
846	
847	    if (bondVecs[bondAtomIndex].length() < REALLY_SMALL_BOND_LEN) {
848	      // did not find a non-colinear bond
849	
850	      BOOST_LOG(rdWarningLog)
851	          << "Failed to get a representative vector for the defining bond of an atropisomer - atoms are: "
852	          << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
853	          << std::endl;
854	      return false;
855	    }
856	  }
857	
858	  // first see if any candidate bond is already set to a wedge or hash
859	  // if so, we will use that bond as a wedge or hash
860	
861	  std::vector<int> useBondsAtEnd[2];
862	  bool foundBondDir = false;
863	
864	  for (unsigned int whichEnd = 0; whichEnd < 2; ++whichEnd) {
865	    for (unsigned int whichBond = 0;
866	         whichBond < atomAndBondVecs[whichEnd].second.size(); ++whichBond) {
867	      auto bondDir = atomAndBondVecs[whichEnd].second[whichBond]->getBondDir();
868	
869	      // see if it is a wedge or hash and its origin is the atom in the
870	      // main bond
871	
872	      if ((bondDir == Bond::BEGINWEDGE || bondDir == Bond::BEGINDASH) &&
873	          atomAndBondVecs[whichEnd].second[whichBond]->getBeginAtom() ==
874	              atomAndBondVecs[whichEnd].first &&
875	          canHaveDirection(*bond)) {
876	        useBondsAtEnd[whichEnd].push_back(whichBond);
877	        foundBondDir = true;
878	      }
879	    }
880	  }
881	
882	  if (foundBondDir) {
883	    for (unsigned int whichEnd = 0; whichEnd < 2; ++whichEnd) {
884	      for (unsigned int whichBondIndex = 0;
885	           whichBondIndex < useBondsAtEnd[whichEnd].size(); ++whichBondIndex) {
886	        atomAndBondVecs[whichEnd]
887	            .second[useBondsAtEnd[whichEnd][whichBondIndex]]
888	            ->setBondDir(getBondDirForAtropisomer2d(
889	                bondVecs, bond->getStereo(), whichEnd,
890	                useBondsAtEnd[whichEnd][whichBondIndex]));
891	      }
892	    }
893	
894	    return true;
895	  }
896	
897	  // did not find a good bond dir - pick one to use
898	  // we would like to have one that is in a ring, and will favor it being a
899	  // wedge
900	
901	  // We favor rings here because wedging non-ring bonds makes it too likely that
902	  // we'll end up accidentally creating new atropisomeric bonds. This was github
903	  // issue 7371
904	
905	  const RingInfo *ri = bond->getOwningMol().getRingInfo();
906	
907	  int bestBondEnd = -1, bestBondNumber = -1;
908	  bool bestBondIsSingle = false;
909	  unsigned int bestRingCount = INT_MAX;
910	  unsigned int largestRingSize = 0;
911	  Bond::BondDir bestBondDir = Bond::BondDir::NONE;
912	  for (unsigned int whichEnd = 0; whichEnd < 2; ++whichEnd) {
913	    for (unsigned int whichBond = 0;
914	         whichBond < atomAndBondVecs[whichEnd].second.size(); ++whichBond) {
915	      auto bondToTry = atomAndBondVecs[whichEnd].second[whichBond];
916	
917	      if (!canHaveDirection(*bondToTry) ||
918	          wedgeBonds.find(bondToTry->getIdx()) != wedgeBonds.end()) {
919	        continue;  // must be a single OR aromatic bond and not already
920	                   // spoken for by a chiral center
921	      }
922	
923	      if (bondToTry->getBondDir() != Bond::BondDir::NONE) {
924	        if (bondToTry->getBeginAtom()->getIdx() ==
925	            atomAndBondVecs[whichEnd].first->getIdx()) {
926	          if (bondToTry->getBondDir() == Bond::BEGINWEDGE ||
927	              bondToTry->getBondDir() == Bond::BEGINDASH) {
928	            BOOST_LOG(rdWarningLog)
929	                << "Wedge or hash bond found on atropisomer where not expected - atoms are: "
930	                << bond->getBeginAtomIdx() << " " << bond->getEndAtomIdx()
931	                << std::endl;
932	            return false;
933	          } else {
934	            continue;  // probably a slash up or down for a double bond
935	          }
936	        } else {
937	          continue;  // wedge or hash bond affecting the OTHER atom
938	                     // = perhaps a chiral center
939	        }
940	      }
941	      auto ringCount = ri->numBondRings(bondToTry->getIdx());
