#include <GraphMol/FileParsers/FileParsers.h>
#include <GraphMol/MolStandardize/Tautomer.h>
#include <GraphMol/RDKitBase.h>
#include <GraphMol/SmilesParse/SmilesParse.h>
#include <GraphMol/SmilesParse/SmilesWrite.h>

#include <exception>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

namespace {

int failures = 0;

void runCase(const std::string &label, RDKit::ROMol *raw) {
  if (!raw) {
    std::cout << "FAIL " << label << ": could not parse\n";
    ++failures;
    return;
  }
  std::unique_ptr<RDKit::ROMol> mol(raw);
  for (bool removeBondStereo : {true, false}) {
    try {
      RDKit::MolStandardize::TautomerEnumerator enumerator;
      enumerator.setRemoveBondStereo(removeBondStereo);
      std::unique_ptr<RDKit::ROMol> canonical(enumerator.canonicalize(*mol));
      if (!canonical) {
        std::cout << "FAIL " << label
                  << " removeBondStereo=" << removeBondStereo
                  << ": null canonical\n";
        ++failures;
        continue;
      }
      const auto smi = RDKit::MolToSmiles(*canonical);
      if (smi.empty()) {
        std::cout << "FAIL " << label
                  << " removeBondStereo=" << removeBondStereo
                  << ": empty smiles\n";
        ++failures;
        continue;
      }
      // serializability: round it through a parse again
      std::unique_ptr<RDKit::ROMol> reloaded(RDKit::SmilesToMol(smi));
      if (!reloaded) {
        std::cout << "FAIL " << label
                  << " removeBondStereo=" << removeBondStereo
                  << ": canonical smiles does not reparse: " << smi << "\n";
        ++failures;
        continue;
      }
      std::cout << "ok   " << label << " removeBondStereo=" << removeBondStereo
                << ": " << smi << "\n";
    } catch (const std::exception &e) {
      std::cout << "FAIL " << label << " removeBondStereo=" << removeBondStereo
                << ": exception: " << e.what() << "\n";
      ++failures;
    } catch (...) {
      std::cout << "FAIL " << label << " removeBondStereo=" << removeBondStereo
                << ": unknown exception\n";
      ++failures;
    }
  }
}

}  // namespace

int main(int argc, char **argv) {
  if (argc == 2) {
    // treat the argument as a SMILES
    runCase(argv[1], RDKit::SmilesToMol(argv[1]));
    std::cout << (failures ? "BATTERY_FAIL" : "BATTERY_OK") << "\n";
    return failures ? 1 : 0;
  }

  // smiles battery: stereo-bearing molecules of different flavors
  std::vector<std::string> cases = {
      // chiral amino acid
      "N[C@@H](C)C(=O)O",
      "N[C@H](C)C(=O)O",
      // E/Z
      "C/C=C/C",
      "C/C=C\\C",
      // enolizable E/Z
      "C/C=C/O",
      "CC(O)=CC",
      // amides/enamides akin to the fixture
      "C/C=C\\NC(C)=O",
      "CC=CNC(C)=O",
      "CNC(C)=O",
      "CCCN=C(C)O",
      // atropisomer via CXSMILES wedged-bond labels
      "c1ccc(-c2ccccc2)cc1 |wU:1.1|",
      "c1ccc(-c2ccccc2)cc1 |wD:1.1|",
      // ring stereo / meso-ish
      "C[C@H]1CC[C@@H](C)CC1",
      // guanidine-like tautomerism with stereo nearby
      "C[C@H](N)C(=N)N",
      // imidic acid / nitroso-oxime style
      "C(=NO)c1ccccc1",
      // pyridone with a stereocenter substituent
      "O=c1[nH]cccc1C[C@@H](C)O",
      // larger acyclic with several stereo annotations
      "C/C=C\\C[C@@H](O)C(=O)N[C@H](C)C(=O)O",
  };
  for (const auto &smi : cases) {
    runCase(smi, RDKit::SmilesToMol(smi));
  }

  // V3000 round-trip battery: parse -> write V3000 -> parse -> workflow
  std::vector<std::string> v3k = {
      "N[C@@H](C)C(=O)O",
      "C/C=C\\NC(C)=O",
      "c1ccc(-c2ccccc2)cc1 |wU:1.1|",
      "CC(O)=C[C@H](C)N",
  };
  for (const auto &smi : v3k) {
    std::unique_ptr<RDKit::ROMol> m(RDKit::SmilesToMol(smi));
    if (!m) {
      std::cout << "FAIL v3k prep " << smi << "\n";
      ++failures;
      continue;
    }
    RDKit::SmilesWriteParams wp;
    const auto block = RDKit::MolToV3KMolBlock(*m);
    runCase("v3k:" + smi, RDKit::MolBlockToMol(block));
  }

  std::cout << (failures ? "BATTERY_FAIL" : "BATTERY_OK") << "\n";
  return failures ? 1 : 0;
}

