#include <GraphMol/RDKitBase.h>
#include <GraphMol/SmilesParse/SmilesParse.h>
#include <GraphMol/SmilesParse/SmilesWrite.h>

#include <iostream>
#include <memory>
#include <string>
#include <vector>

int main() {
  std::vector<std::string> cases = {
      "c1ccc(-c2ccccc2)cc1 |wU:1.1|",
      "c1ccc(-c2ccccc2)cc1 |wD:1.1|",
      "C=C(C)c1cccc([C@@H](C)O)c1 |wD:3.3|",
  };
  int rc = 0;
  for (const auto &in : cases) {
    std::unique_ptr<RDKit::ROMol> m(RDKit::SmilesToMol(in));
    if (!m) {
      std::cout << "parse failed: " << in << "\n";
      rc = 1;
      continue;
    }
    std::string atrop;
    for (const auto b : m->bonds()) {
      if (b->getStereo() == RDKit::Bond::STEREOATROPCW ||
          b->getStereo() == RDKit::Bond::STEREOATROPCCW) {
        atrop += (atrop.empty() ? "" : ",") + std::to_string(b->getIdx());
      }
    }
    // canonical + isomeric (this is what tautomer dedup/picking writes)
    const auto out = RDKit::MolToSmiles(*m, true, true);
    std::cout << "in=" << in << " atropBonds=[" << atrop << "] canonOut=" << out
              << "\n";
    if (!atrop.empty() && out.find("w") == std::string::npos) {
      std::cout << "  -> atrop stereo LOST during canonical smiles write\n";
      rc = 1;
    }
  }
  return rc;
}

